// Faithful low-level Rust representation of the MSM8960 MMCC implementation.
// The clock-provider structures and operations below are supplied by the
// surrounding kernel translation and are intentionally referenced as externals.

#![allow(non_camel_case_types, non_snake_case, dead_code, unused_variables)]

