#[repr(u32)]
#[derive(Copy, Clone)]
enum Parent {
    P_PXO,
    P_PLL8,
    P_PLL2,
    P_PLL3,
    P_PLL15,
    P_HDMI_PLL,
    P_DSI1_PLL_DSICLK,
    P_DSI2_PLL_DSICLK,
    P_DSI1_PLL_BYTECLK,
    P_DSI2_PLL_BYTECLK,
    P_LVDS_PLL,
}

#[repr(C)]
#[derive(Copy, Clone)]
pub struct FreqTbl {
    pub freq: u32,
    pub src: Parent,
    pub pre_div: u32,
    pub m: u32,
    pub n: u32,
}

const fn f_mn(freq: u32, src: Parent, m: u32, n: u32) -> FreqTbl {
    FreqTbl { freq, src, pre_div: 0, m, n }
}

